// SPDX-License-Identifier: Apache-2.0
// Checks for url-template, bloom-filter, stats-summary, interval-merge, shell-quote, number-to-words,
// pagination-window, text-wrap, markdown-table and ndjson. Vector literals are generated by a script from the shared
// wave 12 vectors.json. Strings are compared as Unicode scalars because Swift String equality treats canonically
// equivalent text as equal. Pagination gaps are nil.
import GenlibSwift

private func scalars(_ s: String) -> [UInt32] { s.unicodeScalars.map(\.value) }
private func same(_ c: inout Checks, _ name: String, _ expected: String, _ actual: () throws -> String) {
    do {
        let v = try actual()
        let ok = scalars(v) == scalars(expected)
        if !ok { print("  expected <\(expected)> got <\(v)>") }
        c.check(name, ok)
    } catch {
        print("  unexpected error: \(error)")
        c.check(name, false)
    }
}
private func sameList(_ c: inout Checks, _ name: String, _ expected: [String], _ actual: () throws -> [String]) {
    do {
        let v = try actual()
        let ok = v.map(scalars) == expected.map(scalars)
        if !ok { print("  expected <\(expected)> got <\(v)>") }
        c.check(name, ok)
    } catch {
        print("  unexpected error: \(error)")
        c.check(name, false)
    }
}
/// Relative tolerance 1e-9 (absolute near zero).
private func close(_ c: inout Checks, _ name: String, _ expected: Double, _ actual: Double?) {
    guard let a = actual else { c.check(name + " (error)", false); return }
    let scale = max(abs(expected), abs(a), 1)
    let ok = abs(expected - a) <= 1e-9 * scale
    if !ok { print("  expected <\(expected)> got <\(a)>") }
    c.check(name, ok)
}
private func u64hex(_ h: UInt64) -> String {
    let s = String(h, radix: 16)
    return String(repeating: "0", count: 16 - s.count) + s
}
private func hist(_ h: StatsSummary.Histogram) -> String { h.counts.map(String.init).joined(separator: ",") + "|\(h.below)|\(h.above)" }
private func json(_ text: String) -> JsonPatch.Value {
    do { return try JsonPatch.parse(text) } catch { fatalError("bad test JSON \(text): \(error)") }
}

func runWave12Checks(_ c: inout Checks) {
    runUrlTemplateChecks(&c)
    runBloomFilterChecks(&c)
    runStatsSummaryChecks(&c)
    runIntervalMergeChecks(&c)
    runShellQuoteChecks(&c)
    runNumberWordsChecks(&c)
    runPaginationWindowChecks(&c)
    runTextWrapChecks(&c)
    runMarkdownTableChecks(&c)
    runNdjsonChecks(&c)
}

