private func runUrlTemplateChecks(_ c: inout Checks) {
    same(&c, "url-template 0", "value") { try UrlTemplate.expand("{var}", templateVars) }
    same(&c, "url-template 1", "Hello%20World%21") { try UrlTemplate.expand("{hello}", templateVars) }
    same(&c, "url-template 2", "50%25") { try UrlTemplate.expand("{half}", templateVars) }
    same(&c, "url-template 3", "OX") { try UrlTemplate.expand("O{empty}X", templateVars) }
    same(&c, "url-template 4", "OX") { try UrlTemplate.expand("O{undef}X", templateVars) }
    same(&c, "url-template 5", "1024,768") { try UrlTemplate.expand("{x,y}", templateVars) }
    same(&c, "url-template 6", "1024,Hello%20World%21,768") { try UrlTemplate.expand("{x,hello,y}", templateVars) }
    same(&c, "url-template 7", "?1024,") { try UrlTemplate.expand("?{x,empty}", templateVars) }
    same(&c, "url-template 8", "?1024") { try UrlTemplate.expand("?{x,undef}", templateVars) }
    same(&c, "url-template 9", "?768") { try UrlTemplate.expand("?{undef,y}", templateVars) }
    same(&c, "url-template 10", "val") { try UrlTemplate.expand("{var:3}", templateVars) }
    same(&c, "url-template 11", "value") { try UrlTemplate.expand("{var:30}", templateVars) }
    same(&c, "url-template 12", "red,green,blue") { try UrlTemplate.expand("{list}", templateVars) }
    same(&c, "url-template 13", "red,green,blue") { try UrlTemplate.expand("{list*}", templateVars) }
    same(&c, "url-template 14", "semi,%3B,dot,.,comma,%2C") { try UrlTemplate.expand("{keys}", templateVars) }
    same(&c, "url-template 15", "semi=%3B,dot=.,comma=%2C") { try UrlTemplate.expand("{keys*}", templateVars) }
    same(&c, "url-template 16", "value") { try UrlTemplate.expand("{+var}", templateVars) }
    same(&c, "url-template 17", "Hello%20World!") { try UrlTemplate.expand("{+hello}", templateVars) }
    same(&c, "url-template 18", "50%25") { try UrlTemplate.expand("{+half}", templateVars) }
    same(&c, "url-template 19", "http%3A%2F%2Fexample.com%2Fhome%2Findex") { try UrlTemplate.expand("{base}index", templateVars) }
    same(&c, "url-template 20", "http://example.com/home/index") { try UrlTemplate.expand("{+base}index", templateVars) }
    same(&c, "url-template 21", "/foo/b/here") { try UrlTemplate.expand("{+path:6}/here", templateVars) }
    same(&c, "url-template 22", "red,green,blue") { try UrlTemplate.expand("{+list}", templateVars) }
    same(&c, "url-template 23", "semi=;,dot=.,comma=,") { try UrlTemplate.expand("{+keys*}", templateVars) }
    same(&c, "url-template 24", "#value") { try UrlTemplate.expand("{#var}", templateVars) }
    same(&c, "url-template 25", "#Hello%20World!") { try UrlTemplate.expand("{#hello}", templateVars) }
    same(&c, "url-template 26", "#/foo/b/here") { try UrlTemplate.expand("{#path:6}/here", templateVars) }
    same(&c, "url-template 27", "#semi=;,dot=.,comma=,") { try UrlTemplate.expand("{#keys*}", templateVars) }
    same(&c, "url-template 28", "X.value") { try UrlTemplate.expand("X{.var}", templateVars) }
    same(&c, "url-template 29", "X.val") { try UrlTemplate.expand("X{.var:3}", templateVars) }
    same(&c, "url-template 30", "X.red.green.blue") { try UrlTemplate.expand("X{.list*}", templateVars) }
    same(&c, "url-template 31", ".example.com") { try UrlTemplate.expand("{.dom*}", templateVars) }
    same(&c, "url-template 32", "/value") { try UrlTemplate.expand("{/var}", templateVars) }
    same(&c, "url-template 33", "/v/value") { try UrlTemplate.expand("{/var:1,var}", templateVars) }
    same(&c, "url-template 34", "/red/green/blue/%2Ffoo") { try UrlTemplate.expand("{/list*,path:4}", templateVars) }
    same(&c, "url-template 35", "/semi=%3B/dot=./comma=%2C") { try UrlTemplate.expand("{/keys*}", templateVars) }
    same(&c, "url-template 36", ";hello=Hello") { try UrlTemplate.expand("{;hello:5}", templateVars) }
    same(&c, "url-template 37", ";list=red;list=green;list=blue") { try UrlTemplate.expand("{;list*}", templateVars) }
    same(&c, "url-template 38", ";semi=%3B;dot=.;comma=%2C") { try UrlTemplate.expand("{;keys*}", templateVars) }
    same(&c, "url-template 39", ";x=1024;y=768;empty") { try UrlTemplate.expand("{;x,y,empty}", templateVars) }
    same(&c, "url-template 40", "?x=1024&y=768&empty=") { try UrlTemplate.expand("{?x,y,empty}", templateVars) }
    same(&c, "url-template 41", "?var=val") { try UrlTemplate.expand("{?var:3}", templateVars) }
    same(&c, "url-template 42", "?list=red,green,blue") { try UrlTemplate.expand("{?list}", templateVars) }
    same(&c, "url-template 43", "?list=red&list=green&list=blue") { try UrlTemplate.expand("{?list*}", templateVars) }
    same(&c, "url-template 44", "?keys=semi,%3B,dot,.,comma,%2C") { try UrlTemplate.expand("{?keys}", templateVars) }
    same(&c, "url-template 45", "?semi=%3B&dot=.&comma=%2C") { try UrlTemplate.expand("{?keys*}", templateVars) }
    same(&c, "url-template 46", "&var=val") { try UrlTemplate.expand("{&var:3}", templateVars) }
    same(&c, "url-template 47", "&semi=%3B&dot=.&comma=%2C") { try UrlTemplate.expand("{&keys*}", templateVars) }
    same(&c, "url-template 48", "") { try UrlTemplate.expand("{?empty_keys*}", templateVars) }
    same(&c, "url-template 49", "") { try UrlTemplate.expand("{?empty_list}", templateVars) }
    same(&c, "url-template 50", "/one/two/three") { try UrlTemplate.expand("{/count*}", templateVars) }
    same(&c, "url-template 51", "caf%C3%A9%20%E2%98%83") { try UrlTemplate.expand("{utf}", templateVars) }
    same(&c, "url-template 52", "caf%C3%A9%20%E2%98%83") { try UrlTemplate.expand("{+utf}", templateVars) }
    same(&c, "url-template 53", "%F0%9F%98%80") { try UrlTemplate.expand("{emoji:1}", templateVars) }
    same(&c, "url-template 54", "?utf=caf%C3%A9%20%E2%98%83") { try UrlTemplate.expand("{?utf}", templateVars) }
    same(&c, "url-template 55", "map?1024,768#Hello%20World%21") { try UrlTemplate.expand("map?{x,y}#{hello}", templateVars) }
    same(&c, "url-template 56", "literal%20kept/value") { try UrlTemplate.expand("literal%20kept/{var}", templateVars) }
    same(&c, "url-template 57", "sp%20acevalue") { try UrlTemplate.expand("sp ace{var}", templateVars) }
    c.throwsError("url-template invalid 0", { _ = try UrlTemplate.expand("{var", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 1", { _ = try UrlTemplate.expand("var}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 2", { _ = try UrlTemplate.expand("{}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 3", { _ = try UrlTemplate.expand("{=var}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 4", { _ = try UrlTemplate.expand("{!var}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 5", { _ = try UrlTemplate.expand("{@var}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 6", { _ = try UrlTemplate.expand("{|var}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 7", { _ = try UrlTemplate.expand("{var:0}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 8", { _ = try UrlTemplate.expand("{var:10000}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 9", { _ = try UrlTemplate.expand("{va r}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 10", { _ = try UrlTemplate.expand("{list:3}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 11", { _ = try UrlTemplate.expand("{keys:2}", templateVars) }, where: { $0 is UrlTemplateError })
    c.throwsError("url-template invalid 12", { _ = try UrlTemplate.expand("{var:01}", templateVars) }, where: { $0 is UrlTemplateError })
}

private func runBloomFilterChecks(_ c: inout Checks) {
    c.eq("bloom fnv1a64 0", "f74a62a458befdbf", u64hex(BloomFilter.fnv1a64("apple".utf8)))
    c.eq("bloom fnv1a64 1", "b4d3b6b1c372c890", u64hex(BloomFilter.fnv1a64("banana".utf8)))
    c.eq("bloom fnv1a64 2", "cbf29ce484222325", u64hex(BloomFilter.fnv1a64("".utf8)))
    c.eq("bloom fnv1a64 3", "48e8823acfa40d89", u64hex(BloomFilter.fnv1a64("café".utf8)))
    c.eq("bloom fnv1a64 4", "feff073875020288", u64hex(BloomFilter.fnv1a64("😀".utf8)))
    c.eq("bloom fnv1a64 5", "6c151ea4dcd221c2", u64hex(BloomFilter.fnv1a64("user:42".utf8)))
    c.eq("bloom fnv1a64 6", "060324515a7b4e27", u64hex(BloomFilter.fnv1a64("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".utf8)))
    c.eq("bloom sizeFor 0", "8/6", try { let r = try BloomFilter.sizeFor(n: 1, p: 0.5); return "\(r.m)/\(r.k)" }())
    c.eq("bloom sizeFor 1", "96/7", try { let r = try BloomFilter.sizeFor(n: 10, p: 0.01); return "\(r.m)/\(r.k)" }())
    c.eq("bloom sizeFor 2", "959/7", try { let r = try BloomFilter.sizeFor(n: 100, p: 0.01); return "\(r.m)/\(r.k)" }())
    c.eq("bloom sizeFor 3", "14378/10", try { let r = try BloomFilter.sizeFor(n: 1000, p: 0.001); return "\(r.m)/\(r.k)" }())
    c.eq("bloom sizeFor 4", "31177/4", try { let r = try BloomFilter.sizeFor(n: 5000, p: 0.05); return "\(r.m)/\(r.k)" }())
    c.eq("bloom sizeFor 5", "8/2", try { let r = try BloomFilter.sizeFor(n: 3, p: 0.3); return "\(r.m)/\(r.k)" }())
    c.throwsError("bloom invalid size 0", { _ = try BloomFilter.sizeFor(n: 0, p: 0.1) }, where: { $0 is BloomFilterError })
    c.throwsError("bloom invalid size 1", { _ = try BloomFilter.sizeFor(n: 10, p: 0.0) }, where: { $0 is BloomFilterError })
    c.throwsError("bloom invalid size 2", { _ = try BloomFilter.sizeFor(n: 10, p: 1.0) }, where: { $0 is BloomFilterError })
    c.throwsError("bloom invalid size 3", { _ = try BloomFilter.sizeFor(n: 10, p: 1.5) }, where: { $0 is BloomFilterError })
    guard var b = try? BloomFilter(m: 256, k: 5) else { c.check("bloom init", false); return }
    c.eq("bloom positions 0", [191, 99, 7, 171, 79], b.positions("apple"))
    c.eq("bloom positions 1", [144, 65, 242, 163, 84], b.positions("banana"))
    c.eq("bloom positions 2", [37, 9, 237, 209, 181], b.positions(""))
    c.eq("bloom positions 3", [137, 195, 253, 55, 113], b.positions("café"))
    c.eq("bloom positions 4", [136, 192, 248, 48, 104], b.positions("😀"))
    c.eq("bloom positions 5", [194, 102, 10, 174, 82], b.positions("user:42"))
    c.eq("bloom positions 6", [39, 120, 201, 26, 107], b.positions("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"))
    b.add("apple")
    b.add("banana")
    b.add("")
    b.add("café")
    b.add("😀")
    c.eq("bloom serialized", "gAIAACAAgQACgBAACAECAAADAQAICCCACQACAAAgBCE", b.serialize())
    c.eq("bloom probe 0", true, b.mightContain("apple"))
    c.eq("bloom probe 1", true, b.mightContain("banana"))
    c.eq("bloom probe 2", true, b.mightContain(""))
    c.eq("bloom probe 3", true, b.mightContain("café"))
    c.eq("bloom probe 4", true, b.mightContain("😀"))
    c.eq("bloom probe 5", false, b.mightContain("cherry"))
    c.eq("bloom probe 6", false, b.mightContain("user:42"))
    c.eq("bloom probe 7", false, b.mightContain("zzz"))
    c.eq("bloom probe 8", false, b.mightContain("Apple"))
    c.eq("bloom count estimate", 5, b.countEstimate())
    c.eq("bloom deserialize round trip", "gAIAACAAgQACgBAACAECAAADAQAICCCACQACAAAgBCE", try BloomFilter.deserialize(m: 256, k: 5, "gAIAACAAgQACgBAACAECAAADAQAICCCACQACAAAgBCE").serialize())
    c.throwsError("bloom deserialize wrong length", { _ = try BloomFilter.deserialize(m: 256, k: 5, "AAAA") }, where: { $0 is BloomFilterError })
    do {
        var cherry = try BloomFilter(m: 256, k: 5)
        cherry.add("cherry")
        let u = try b.union(cherry)
        c.eq("bloom union with cherry", "gAIAACAAgQACgBAACAESAAADIQAICGCACQCCAAAgBCE", u.serialize())
        c.eq("bloom union count", 6, u.countEstimate())
        let other = try BloomFilter(m: 256, k: 6)
        c.throwsError("bloom union mismatch", { _ = try b.union(other) }, where: { $0 is BloomFilterError })
        var full = try BloomFilter(m: 8, k: 1)
        for i in 0..<200 { full.add("x\(i)") }
        c.eq("bloom saturated estimate", nil, full.countEstimate())
    } catch { c.check("bloom union setup: \(error)", false) }
    c.throwsError("bloom bad params", { _ = try BloomFilter(m: 7, k: 1) }, where: { $0 is BloomFilterError })
}

private func runStatsSummaryChecks(_ c: inout Checks) {
    do {
        let s = try StatsSummary.summary([1.0])
        c.eq("stats summary 0 count", 1, s.count)
        close(&c, "stats summary 0 sum", 1.0, s.sum)
        close(&c, "stats summary 0 min", 1.0, s.min)
        close(&c, "stats summary 0 max", 1.0, s.max)
        close(&c, "stats summary 0 mean", 1.0, s.mean)
        close(&c, "stats summary 0 median", 1.0, s.median)
        close(&c, "stats summary 0 variance", 0.0, s.variance)
        close(&c, "stats summary 0 stddev", 0.0, s.stddev)
        close(&c, "stats summary 0 p25", 1.0, s.p25)
        close(&c, "stats summary 0 p75", 1.0, s.p75)
        close(&c, "stats summary 0 p90", 1.0, s.p90)
        close(&c, "stats summary 0 p95", 1.0, s.p95)
        close(&c, "stats summary 0 p99", 1.0, s.p99)
    } catch { c.check("stats summary 0: \(error)", false) }
    do {
        let s = try StatsSummary.summary([1.0, 2.0])
        c.eq("stats summary 1 count", 2, s.count)
        close(&c, "stats summary 1 sum", 3.0, s.sum)
        close(&c, "stats summary 1 min", 1.0, s.min)
        close(&c, "stats summary 1 max", 2.0, s.max)
        close(&c, "stats summary 1 mean", 1.5, s.mean)
        close(&c, "stats summary 1 median", 1.5, s.median)
        close(&c, "stats summary 1 variance", 0.5, s.variance)
        close(&c, "stats summary 1 stddev", 0.7071067811865476, s.stddev)
        close(&c, "stats summary 1 p25", 1.25, s.p25)
        close(&c, "stats summary 1 p75", 1.75, s.p75)
        close(&c, "stats summary 1 p90", 1.9, s.p90)
        close(&c, "stats summary 1 p95", 1.95, s.p95)
        close(&c, "stats summary 1 p99", 1.99, s.p99)
    } catch { c.check("stats summary 1: \(error)", false) }
    do {
        let s = try StatsSummary.summary([3.0, 1.0, 2.0])
        c.eq("stats summary 2 count", 3, s.count)
        close(&c, "stats summary 2 sum", 6.0, s.sum)
        close(&c, "stats summary 2 min", 1.0, s.min)
        close(&c, "stats summary 2 max", 3.0, s.max)
        close(&c, "stats summary 2 mean", 2.0, s.mean)
        close(&c, "stats summary 2 median", 2.0, s.median)
        close(&c, "stats summary 2 variance", 1.0, s.variance)
        close(&c, "stats summary 2 stddev", 1.0, s.stddev)
        close(&c, "stats summary 2 p25", 1.5, s.p25)
        close(&c, "stats summary 2 p75", 2.5, s.p75)
        close(&c, "stats summary 2 p90", 2.8, s.p90)
        close(&c, "stats summary 2 p95", 2.9, s.p95)
        close(&c, "stats summary 2 p99", 2.98, s.p99)
    } catch { c.check("stats summary 2: \(error)", false) }
    do {
        let s = try StatsSummary.summary([2.0, 4.0, 4.0, 4.0, 5.0, 5.0, 7.0, 9.0])
        c.eq("stats summary 3 count", 8, s.count)
        close(&c, "stats summary 3 sum", 40.0, s.sum)
        close(&c, "stats summary 3 min", 2.0, s.min)
        close(&c, "stats summary 3 max", 9.0, s.max)
        close(&c, "stats summary 3 mean", 5.0, s.mean)
        close(&c, "stats summary 3 median", 4.5, s.median)
        close(&c, "stats summary 3 variance", 4.571428571428571, s.variance)
        close(&c, "stats summary 3 stddev", 2.138089935299395, s.stddev)
        close(&c, "stats summary 3 p25", 4.0, s.p25)
        close(&c, "stats summary 3 p75", 5.5, s.p75)
        close(&c, "stats summary 3 p90", 7.6, s.p90)
