        close(&c, "stats summary 3 p99", 8.86, s.p99)
    } catch { c.check("stats summary 3: \(error)", false) }
    do {
        let s = try StatsSummary.summary([1.5, 2.5, -3.25, 10.0, 0.0])
        c.eq("stats summary 4 count", 5, s.count)
        close(&c, "stats summary 4 sum", 10.75, s.sum)
        close(&c, "stats summary 4 min", -3.25, s.min)
        close(&c, "stats summary 4 max", 10.0, s.max)
