        close(&c, "stats summary 4 p95", 8.499999999999998, s.p95)
        close(&c, "stats summary 4 p99", 9.7, s.p99)
    } catch { c.check("stats summary 4: \(error)", false) }
    do {
        let s = try StatsSummary.summary([10.0, 20.0, 30.0, 40.0, 50.0, 60.0, 70.0, 80.0, 90.0, 100.0])
        c.eq("stats summary 5 count", 10, s.count)
        close(&c, "stats summary 5 sum", 550.0, s.sum)
