        close(&c, "stats summary 5 stddev", 30.276503540974915, s.stddev)
        close(&c, "stats summary 5 p25", 32.5, s.p25)
        close(&c, "stats summary 5 p75", 77.5, s.p75)
        close(&c, "stats summary 5 p90", 91.0, s.p90)
        close(&c, "stats summary 5 p95", 95.5, s.p95)
        close(&c, "stats summary 5 p99", 99.1, s.p99)
    } catch { c.check("stats summary 5: \(error)", false) }
    do {
        let s = try StatsSummary.summary([1000000004.0, 1000000007.0, 1000000013.0, 1000000016.0])
        c.eq("stats summary 6 count", 4, s.count)
        close(&c, "stats summary 6 sum", 4000000040.0, s.sum)
        close(&c, "stats summary 6 min", 1000000004.0, s.min)
