private func runIntervalMergeChecks(_ c: inout Checks) {
    c.eq("intervals merge 0", [.init(1, 6), .init(8, 10), .init(15, 20)], try IntervalMerge.merge([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)]))
    c.eq("intervals merge 1", [.init(1, 3), .init(5, 7)], try IntervalMerge.merge([.init(5, 7), .init(1, 2), .init(2, 3)]))
    c.eq("intervals merge 2", [], try IntervalMerge.merge([]))
    c.eq("intervals merge 3", [.init(-5, 4)], try IntervalMerge.merge([.init(-5, -1), .init(-3, 4)]))
    c.eq("intervals intersect 0", [.init(1, 2), .init(5, 6), .init(8, 9), .init(17, 20)], try IntervalMerge.intersect([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], [.init(0, 2), .init(5, 9), .init(17, 30)]))
    c.eq("intervals intersect 1", [], try IntervalMerge.intersect([.init(1, 2)], [.init(2, 3)]))
    c.eq("intervals intersect 2", [.init(10, 20), .init(30, 40)], try IntervalMerge.intersect([.init(0, 100)], [.init(10, 20), .init(30, 40)]))
    c.eq("intervals subtract 0", [.init(2, 5), .init(9, 10), .init(15, 17)], try IntervalMerge.subtract([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], [.init(0, 2), .init(5, 9), .init(17, 30)]))
    c.eq("intervals subtract 1", [.init(0, 2), .init(3, 5), .init(7, 10)], try IntervalMerge.subtract([.init(0, 10)], [.init(2, 3), .init(5, 7)]))
    c.eq("intervals subtract 2", [], try IntervalMerge.subtract([.init(0, 10)], [.init(0, 10)]))
    c.eq("intervals subtract 3", [.init(0, 10)], try IntervalMerge.subtract([.init(0, 10)], []))
    c.eq("intervals gaps 0", [.init(0, 1), .init(6, 8), .init(10, 15), .init(20, 25)], try IntervalMerge.gaps([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], lo: 0, hi: 25))
    c.eq("intervals gaps 1", [.init(3, 5)], try IntervalMerge.gaps([], lo: 3, hi: 5))
    c.eq("intervals total 0", 12, try IntervalMerge.total([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)]))
    c.eq("intervals total 1", 19, try IntervalMerge.total([.init(0, 2), .init(5, 9), .init(17, 30)]))
    c.eq("intervals overlaps 0", true, try IntervalMerge.overlaps(.init(1, 3), .init(2, 4)))
    c.eq("intervals overlaps 1", false, try IntervalMerge.overlaps(.init(1, 3), .init(3, 4)))
    c.eq("intervals overlaps 2", true, try IntervalMerge.overlaps(.init(5, 9), .init(6, 7)))
    c.eq("intervals overlaps 3", false, try IntervalMerge.overlaps(.init(1, 2), .init(5, 6)))
    c.eq("intervals contains 0", false, try IntervalMerge.contains([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], 6))
    c.eq("intervals contains 1", true, try IntervalMerge.contains([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], 5))
    c.eq("intervals contains 2", false, try IntervalMerge.contains([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], 20))
    c.eq("intervals contains 3", true, try IntervalMerge.contains([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], 19))
    c.eq("intervals contains 4", false, try IntervalMerge.contains([.init(1, 3), .init(2, 6), .init(8, 10), .init(15, 18), .init(18, 20)], 0))
    c.throwsError("intervals invalid merge 0", { _ = try IntervalMerge.merge([.init(3, 3)]) }, where: { $0 is IntervalMergeError })
    c.throwsError("intervals invalid overlaps 0", { _ = try IntervalMerge.overlaps(.init(3, 3), .init(0, 1)) }, where: { $0 is IntervalMergeError })
    c.throwsError("intervals invalid merge 1", { _ = try IntervalMerge.merge([.init(5, 1)]) }, where: { $0 is IntervalMergeError })
    c.throwsError("intervals invalid overlaps 1", { _ = try IntervalMerge.overlaps(.init(5, 1), .init(0, 1)) }, where: { $0 is IntervalMergeError })
    c.throwsError("intervals invalid gaps bounds", { _ = try IntervalMerge.gaps([], lo: 5, hi: 5) }, where: { $0 is IntervalMergeError })
}

private func runShellQuoteChecks(_ c: inout Checks) {
    same(&c, "shell quote 0", "''") { ShellQuote.quote("") }
    same(&c, "shell quote 1", "abc") { ShellQuote.quote("abc") }
    same(&c, "shell quote 2", "'a b'") { ShellQuote.quote("a b") }
    same(&c, "shell quote 3", "'it'\\''s'") { ShellQuote.quote("it's") }
    same(&c, "shell quote 4", "'a\"b'") { ShellQuote.quote("a\"b") }
    same(&c, "shell quote 5", "'$HOME'") { ShellQuote.quote("$HOME") }
    same(&c, "shell quote 6", "'*.txt'") { ShellQuote.quote("*.txt") }
    same(&c, "shell quote 7", "x=1") { ShellQuote.quote("x=1") }
    same(&c, "shell quote 8", "path/to/file.txt") { ShellQuote.quote("path/to/file.txt") }
    same(&c, "shell quote 9", "'tab\there'") { ShellQuote.quote("tab\there") }
    same(&c, "shell quote 10", "'line\nbreak'") { ShellQuote.quote("line\nbreak") }
    same(&c, "shell quote 11", "'é'") { ShellQuote.quote("é") }
    same(&c, "shell quote 12", "-n") { ShellQuote.quote("-n") }
    same(&c, "shell quote 13", "'~user'") { ShellQuote.quote("~user") }
    same(&c, "shell quote 14", "'!bang'") { ShellQuote.quote("!bang") }
    same(&c, "shell quote 15", "''\\'''\\'''") { ShellQuote.quote("''") }
    same(&c, "shell join 0", "ls -la 'my file' 'it'\\''s'") { ShellQuote.join(["ls", "-la", "my file", "it's"]) }
    same(&c, "shell join 1", "") { ShellQuote.join([String]()) }
    sameList(&c, "shell split 0", ["a", "b", "c"]) { try ShellQuote.split("a b  c") }
    sameList(&c, "shell split 1", ["a b", "c"]) { try ShellQuote.split("'a b' c") }
    sameList(&c, "shell split 2", ["a b", "c"]) { try ShellQuote.split("\"a b\" c") }
    sameList(&c, "shell split 3", ["a b"]) { try ShellQuote.split("a\\ b") }
    sameList(&c, "shell split 4", ["say \"hi\""]) { try ShellQuote.split("\"say \\\"hi\\\"\"") }
    sameList(&c, "shell split 5", ["keep \\n and \\x"]) { try ShellQuote.split("\"keep \\n and \\x\"") }
    sameList(&c, "shell split 6", ["no \\escape"]) { try ShellQuote.split("'no \\escape'") }
    sameList(&c, "shell split 7", ["xyzw"]) { try ShellQuote.split("x\"y\"'z'w") }
    sameList(&c, "shell split 8", ["", ""]) { try ShellQuote.split("'' \"\"") }
    sameList(&c, "shell split 9", ["a", "b", "c"]) { try ShellQuote.split("a\tb\nc") }
    sameList(&c, "shell split 10", ["echo", "$HOME", "*.txt", "~"]) { try ShellQuote.split("echo $HOME *.txt ~") }
    sameList(&c, "shell split 11", ["ab"]) { try ShellQuote.split("\"a\\\nb\"") }
    sameList(&c, "shell split 12", ["ab"]) { try ShellQuote.split("a\\\nb") }
    sameList(&c, "shell split 13", [String]()) { try ShellQuote.split("# comment") }
    sameList(&c, "shell split 14", ["cmd"]) { try ShellQuote.split("cmd # trailing comment") }
    sameList(&c, "shell split 15", ["a#b"]) { try ShellQuote.split("a#b") }
    sameList(&c, "shell split 16", ["$x"]) { try ShellQuote.split("\"$x\"") }
    sameList(&c, "shell split 17", ["lead", "trail"]) { try ShellQuote.split("  lead  trail  ") }
    sameList(&c, "shell roundtrip 0", [""]) { try ShellQuote.split(ShellQuote.quote("")) }
    sameList(&c, "shell roundtrip 1", ["abc"]) { try ShellQuote.split(ShellQuote.quote("abc")) }
    sameList(&c, "shell roundtrip 2", ["a b"]) { try ShellQuote.split(ShellQuote.quote("a b")) }
    sameList(&c, "shell roundtrip 3", ["it's"]) { try ShellQuote.split(ShellQuote.quote("it's")) }
    sameList(&c, "shell roundtrip 4", ["a\"b"]) { try ShellQuote.split(ShellQuote.quote("a\"b")) }
    sameList(&c, "shell roundtrip 5", ["$HOME"]) { try ShellQuote.split(ShellQuote.quote("$HOME")) }
    sameList(&c, "shell roundtrip 6", ["*.txt"]) { try ShellQuote.split(ShellQuote.quote("*.txt")) }
    sameList(&c, "shell roundtrip 7", ["x=1"]) { try ShellQuote.split(ShellQuote.quote("x=1")) }
    sameList(&c, "shell roundtrip 8", ["path/to/file.txt"]) { try ShellQuote.split(ShellQuote.quote("path/to/file.txt")) }
    sameList(&c, "shell roundtrip 9", ["tab\there"]) { try ShellQuote.split(ShellQuote.quote("tab\there")) }
    sameList(&c, "shell roundtrip 10", ["line\nbreak"]) { try ShellQuote.split(ShellQuote.quote("line\nbreak")) }
    sameList(&c, "shell roundtrip 11", ["é"]) { try ShellQuote.split(ShellQuote.quote("é")) }
    sameList(&c, "shell roundtrip 12", ["-n"]) { try ShellQuote.split(ShellQuote.quote("-n")) }
    sameList(&c, "shell roundtrip 13", ["~user"]) { try ShellQuote.split(ShellQuote.quote("~user")) }
    sameList(&c, "shell roundtrip 14", ["!bang"]) { try ShellQuote.split(ShellQuote.quote("!bang")) }
    sameList(&c, "shell roundtrip 15", ["''"]) { try ShellQuote.split(ShellQuote.quote("''")) }
    c.throwsError("shell invalid split 0", { _ = try ShellQuote.split("'open") }, where: { $0 is ShellQuoteError })
    c.throwsError("shell invalid split 1", { _ = try ShellQuote.split("\"open") }, where: { $0 is ShellQuoteError })
    c.throwsError("shell invalid split 2", { _ = try ShellQuote.split("trail\\") }, where: { $0 is ShellQuoteError })
    c.throwsError("shell invalid split 3", { _ = try ShellQuote.split("\"bad \\") }, where: { $0 is ShellQuoteError })
}

