private func runPaginationWindowChecks(_ c: inout Checks) {
    c.eq("pagination page count 0", 1, try PaginationWindow.pageCount(0, perPage: 10))
    c.eq("pagination page count 1", 1, try PaginationWindow.pageCount(1, perPage: 10))
    c.eq("pagination page count 2", 1, try PaginationWindow.pageCount(10, perPage: 10))
