private func runTextWrapChecks(_ c: inout Checks) {
    same(&c, "text wrap 0", "T\nh\ne\nq\nu\ni\nc\nk\nb\nr\no\nw\nn\nf\no\nx\nj\nu\nm\np\ns\no\nv\ne\nr\nt\nh\ne\nl\na\nz\ny\nd\no\ng") { try TextWrap.wrap("The quick brown fox jumps over the lazy dog", width: 1) }
    same(&c, "text wrap 1", "The\nquick\nbrown\nfox\njumps\nover\nthe\nlazy\ndog") { try TextWrap.wrap("The quick brown fox jumps over the lazy dog", width: 5) }
    same(&c, "text wrap 2", "The quick\nbrown fox\njumps over\nthe lazy\ndog") { try TextWrap.wrap("The quick brown fox jumps over the lazy dog", width: 10) }
    same(&c, "text wrap 3", "The quick brown fox\njumps over the lazy\ndog") { try TextWrap.wrap("The quick brown fox jumps over the lazy dog", width: 20) }
    same(&c, "text wrap 4", "a\nb\nc") { try TextWrap.wrap("a  b\t\tc", width: 1) }
    same(&c, "text wrap 5", "a b c") { try TextWrap.wrap("a  b\t\tc", width: 5) }
    same(&c, "text wrap 6", "a b c") { try TextWrap.wrap("a  b\t\tc", width: 10) }
    same(&c, "text wrap 7", "a b c") { try TextWrap.wrap("a  b\t\tc", width: 20) }
    same(&c, "text wrap 8", "s\nu\np\ne\nr\nc\na\nl\ni\nf\nr\na\ng\ni\nl\ni\ns\nt\ni\nc\ne\nx\np\ni\na\nl\ni\nd\no\nc\ni\no\nu\ns\nw\no\nr\nd") { try TextWrap.wrap("supercalifragilisticexpialidocious word", width: 1) }
    same(&c, "text wrap 9", "super\ncalif\nragil\nistic\nexpia\nlidoc\nious\nword") { try TextWrap.wrap("supercalifragilisticexpialidocious word", width: 5) }
    same(&c, "text wrap 10", "supercalif\nragilistic\nexpialidoc\nious word") { try TextWrap.wrap("supercalifragilisticexpialidocious word", width: 10) }
    same(&c, "text wrap 11", "supercalifragilistic\nexpialidocious word") { try TextWrap.wrap("supercalifragilisticexpialidocious word", width: 20) }
    same(&c, "text wrap 12", "l\ni\nn\ne\no\nn\ne\nl\ni\nn\ne\nt\nw\no\ni\ns\nl\no\nn\ng\ne\nr\nt\nh\na\nn\nt\ne\nn\n\ne\nn\nd") { try TextWrap.wrap("line one\nline two is longer than ten\n\nend", width: 1) }
    same(&c, "text wrap 13", "line\none\nline\ntwo\nis\nlonge\nr\nthan\nten\n\nend") { try TextWrap.wrap("line one\nline two is longer than ten\n\nend", width: 5) }
    same(&c, "text wrap 14", "line one\nline two\nis longer\nthan ten\n\nend") { try TextWrap.wrap("line one\nline two is longer than ten\n\nend", width: 10) }
    same(&c, "text wrap 15", "line one\nline two is longer\nthan ten\n\nend") { try TextWrap.wrap("line one\nline two is longer than ten\n\nend", width: 20) }
    same(&c, "text wrap 16", "c\na\nf\né\n😀\n😀\n😀\nn\na\nï\nv\ne") { try TextWrap.wrap("café 😀😀😀 naïve", width: 1) }
    same(&c, "text wrap 17", "café\n😀😀😀\nnaïve") { try TextWrap.wrap("café 😀😀😀 naïve", width: 5) }
    same(&c, "text wrap 18", "café 😀😀😀\nnaïve") { try TextWrap.wrap("café 😀😀😀 naïve", width: 10) }
    same(&c, "text wrap 19", "café 😀😀😀 naïve") { try TextWrap.wrap("café 😀😀😀 naïve", width: 20) }
    same(&c, "text wrap 20", "t\nr\na\ni\nl\ni\nn\ng") { try TextWrap.wrap("trailing   ", width: 1) }
    same(&c, "text wrap 21", "trail\ning") { try TextWrap.wrap("trailing   ", width: 5) }
    same(&c, "text wrap 22", "trailing") { try TextWrap.wrap("trailing   ", width: 10) }
    same(&c, "text wrap 23", "trailing") { try TextWrap.wrap("trailing   ", width: 20) }
    same(&c, "text wrap 24", "") { try TextWrap.wrap("", width: 1) }
    same(&c, "text wrap 25", "") { try TextWrap.wrap("", width: 5) }
    same(&c, "text wrap 26", "") { try TextWrap.wrap("", width: 10) }
    same(&c, "text wrap 27", "") { try TextWrap.wrap("", width: 20) }
    same(&c, "text wrap 28", "c\nr\nl\nf\na\nn\nd\nc\nr") { try TextWrap.wrap("crlf\r\nand\rcr", width: 1) }
    same(&c, "text wrap 29", "crlf\nand\ncr") { try TextWrap.wrap("crlf\r\nand\rcr", width: 5) }
    same(&c, "text wrap 30", "crlf\nand\ncr") { try TextWrap.wrap("crlf\r\nand\rcr", width: 10) }
    same(&c, "text wrap 31", "crlf\nand\ncr") { try TextWrap.wrap("crlf\r\nand\rcr", width: 20) }
    same(&c, "text truncate 0", "The quick…") { try TextWrap.truncate("The quick brown fox jumps", maxLen: 15, ellipsis: "…") }
    same(&c, "text truncate 1", "The quick brown fox jumps") { try TextWrap.truncate("The quick brown fox jumps", maxLen: 100, ellipsis: "…") }
    same(&c, "text truncate 2", "Supercali…") { try TextWrap.truncate("Supercalifragilistic", maxLen: 10, ellipsis: "…") }
    same(&c, "text truncate 3", "Hello...") { try TextWrap.truncate("Hello world", maxLen: 8, ellipsis: "...") }
    same(&c, "text truncate 4", "Hi there you") { try TextWrap.truncate("Hi there you", maxLen: 12, ellipsis: "…") }
    same(&c, "text truncate 5", "a b…") { try TextWrap.truncate("a b c d e f g", maxLen: 6, ellipsis: "…") }
    same(&c, "text truncate 6", "😀😀…") { try TextWrap.truncate("😀😀😀😀", maxLen: 3, ellipsis: "…") }
    same(&c, "text truncate 7", "abc") { try TextWrap.truncate("abc", maxLen: 3, ellipsis: "...") }
    same(&c, "text truncate 8", "...") { try TextWrap.truncate("abcd", maxLen: 3, ellipsis: "...") }
    c.throwsError("text invalid wrap 0", { _ = try TextWrap.wrap("abc", width: 0) }, where: { $0 is TextWrapError })
    c.throwsError("text invalid truncate 0", { _ = try TextWrap.truncate("long text", maxLen: 2, ellipsis: "...") }, where: { $0 is TextWrapError })
    c.throwsError("text invalid truncate 1", { _ = try TextWrap.truncate("long text", maxLen: 0, ellipsis: "") }, where: { $0 is TextWrapError })
    same(&c, "text truncate default ellipsis", "Hello…") { try TextWrap.truncate("Hello world", maxLen: 7) }
}

private func runMarkdownTableChecks(_ c: inout Checks) {
    same(&c, "markdown table 0", "| Name  | Qty |\n| ----- | --- |\n| Apple | 3   |\n| Kiwi  | 12  |") { try MarkdownTable.render(headers: ["Name", "Qty"], rows: [["Apple", "3"], ["Kiwi", "12"]], align: nil) }
    same(&c, "markdown table 1", "| a   |   b |  c  |\n| :-- | --: | :-: |\n| 1   |   2 |  3  |") { try MarkdownTable.render(headers: ["a", "b", "c"], rows: [["1", "2", "3"]], align: ["left", "right", "center"]) }
    same(&c, "markdown table 2", "| Pipe\\|col   | Text           |\n| ----------- | -------------- |\n| a\\|b        | line1<br>line2 |\n| back\\\\slash | crlf<br>x      |") { try MarkdownTable.render(headers: ["Pipe|col", "Text"], rows: [["a|b", "line1\nline2"], ["back\\slash", "crlf\r\nx"]], align: nil) }
    same(&c, "markdown table 3", "|  x  |\n| :-: |") { try MarkdownTable.render(headers: ["x"], rows: [[String]](), align: ["center"]) }
    same(&c, "markdown table 4", "|  Café | 😀   |\n| ----: | --- |\n| naïve | ok  |") { try MarkdownTable.render(headers: ["Café", "😀"], rows: [["naïve", "ok"]], align: ["right", nil]) }
    same(&c, "markdown table 5", "|    wide    |\n| :--------: |\n| abcdefghij |") { try MarkdownTable.render(headers: ["wide"], rows: [["abcdefghij"]], align: ["center"]) }
    c.throwsError("markdown table invalid 0", { _ = try MarkdownTable.render(headers: [String](), rows: [[String]](), align: nil) }, where: { $0 is MarkdownTableError })
    c.throwsError("markdown table invalid 1", { _ = try MarkdownTable.render(headers: ["a", "b"], rows: [["1"]], align: nil) }, where: { $0 is MarkdownTableError })
    c.throwsError("markdown table invalid 2", { _ = try MarkdownTable.render(headers: ["a"], rows: [["1"]], align: ["middle"]) }, where: { $0 is MarkdownTableError })
}

private func runNdjsonChecks(_ c: inout Checks) {
    c.eq("ndjson parse 0", [json("{\"a\":1}"), json("{\"b\":[1,2]}")], try Ndjson.parse("{\"a\":1}\n{\"b\":[1,2]}\n"))
    c.eq("ndjson parse 1", [json("1"), json("\"x\""), json("true"), json("null")], try Ndjson.parse("\n  \n1\r\n\"x\"\ntrue\nnull\n"))
    c.eq("ndjson parse 2", [JsonPatch.Value](), try Ndjson.parse(""))
    c.eq("ndjson parse 3", [json("{\"k\":\"café\"}")], try Ndjson.parse("{\"k\":\"café\"}"))
    c.throwsError("ndjson invalid parse 0", { _ = try Ndjson.parse("{\"a\":1}\n{bad}\n") }, where: { ($0 as? NdjsonError) == .invalidLine(2) })
    c.throwsError("ndjson invalid parse 1", { _ = try Ndjson.parse("1 2") }, where: { ($0 as? NdjsonError) == .invalidLine(1) })
    c.throwsError("ndjson invalid parse 2", { _ = try Ndjson.parse("{\"a\":1}\n\n[1,") }, where: { ($0 as? NdjsonError) == .invalidLine(3) })
    same(&c, "ndjson stringify 0", "{\"a\":1,\"b\":[true,null,\"x\"]}\n") { try Ndjson.stringify([.object([("a", .int(1)), ("b", .array([.bool(true), .null, .string("x")]))])]) }
    same(&c, "ndjson stringify 1", "1\n\"two\"\nfalse\n") { try Ndjson.stringify([.int(1), .string("two"), .bool(false)]) }
    same(&c, "ndjson stringify 2", "") { try Ndjson.stringify([]) }
    same(&c, "ndjson stringify 3", "{\"q\":\"say \\\"hi\\\"\\\\ \\n\\t\\u0001 café\"}\n") { try Ndjson.stringify([.object([("q", .string("say \"hi\"\\ \n\t\u{1} café"))])]) }
    same(&c, "ndjson stringify 4", "{\"z\":1,\"a\":2}\n") { try Ndjson.stringify([.object([("z", .int(1)), ("a", .int(2))])]) }
    same(&c, "ndjson stringify 5", "[]\n{}\n") { try Ndjson.stringify([.array([]), .object([])]) }
    same(&c, "ndjson stringify 6", "-42\n0\n") { try Ndjson.stringify([.int(-42), .int(0)]) }
    same(&c, "ndjson round trip via JsonPatch (sorted keys)", "{\"a\":[true],\"b\":1}\n") { try Ndjson.stringify(Ndjson.parse("{\"b\":1,\"a\":[true]}").map(Ndjson.Value.init)) }
}
